    /** Who comes aboard and who goes ashore before a leg, each in the order `aboardOn` gives. */
    changesAt(legIndex: number): { on: Person[]; off: Person[] } {
        const now = this.aboardOn(legIndex);
        if (legIndex === 0) {
            return { on: now, off: [] };
        }
        const before = this.aboardOn(legIndex - 1);
        const nowIds = new Set(now.map((p) => p.id));
        const beforeIds = new Set(before.map((p) => p.id));
        return {
            on: now.filter((p) => !beforeIds.has(p.id)),
            off: before.filter((p) => !nowIds.has(p.id)),
        };
    }

